                {
                    b.Property<int>("Id")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("int");

                    SqlServerPropertyBuilderExtensions.UseIdentityColumn(b.Property<int>("Id"));

                    b.Property<int>("CounterDown")
                        .HasColumnType("int");

                    b.Property<int>("CounterUp")
                        .HasColumnType("int");

                    b.Property<DateTime>("CreatedAt")
                        .HasColumnType("datetime2");

                    b.Property<int?>("DailyFrequency")
                        .HasColumnType("int");

                    b.Property<DateTime?>("DateCompleted")
                        .HasColumnType("datetime2");

                    b.Property<bool?>("Down")
                        .HasColumnType("bit");

                    b.Property<DateTime?>("DueDate")
                        .HasColumnType("datetime2");

                    b.Property<int>("EveryX")
                        .HasColumnType("int");

                    b.Property<double>("GoldCost")
                        .HasColumnType("float");

                    b.Property<int?>("HabitFrequency")
                        .HasColumnType("int");

                    b.Property<bool>("IsActive")
                        .HasColumnType("bit");

                    b.Property<bool>("IsCompleted")
                        .HasColumnType("bit");

                    b.Property<string>("Notes")
                        .HasMaxLength(1000)
                        .HasColumnType("nvarchar(1000)");

                    b.Property<int>("Priority")
                        .HasColumnType("int");

                    b.Property<bool>("RepeatFriday")
                        .HasColumnType("bit");

                    b.Property<bool>("RepeatMonday")
                        .HasColumnType("bit");

                    b.Property<bool>("RepeatSaturday")
                        .HasColumnType("bit");

                    b.Property<bool>("RepeatSunday")
                        .HasColumnType("bit");

                    b.Property<bool>("RepeatThursday")
                        .HasColumnType("bit");

                    b.Property<bool>("RepeatTuesday")
                        .HasColumnType("bit");

                    b.Property<bool>("RepeatWednesday")
                        .HasColumnType("bit");

                    b.Property<int>("SortOrder")
                        .HasColumnType("int");

                    b.Property<DateTime?>("StartDate")
                        .HasColumnType("datetime2");

                    b.Property<int>("Streak")
                        .HasColumnType("int");

                    b.Property<string>("Text")
                        .IsRequired()
                        .HasMaxLength(200)
                        .HasColumnType("nvarchar(200)");

                    b.Property<int>("Type")
                        .HasColumnType("int");

                    b.Property<bool?>("Up")
                        .HasColumnType("bit");

                    b.Property<DateTime?>("UpdatedAt")
                        .HasColumnType("datetime2");

                    b.Property<int>("UserId")
                        .HasColumnType("int");

                    b.Property<double>("Value")
                        .HasColumnType("float");

                    b.HasKey("Id");

                    b.HasIndex("UserId", "Type");

                    b.ToTable("HabitTasks");
